using System;
using System.IO;
using System.Text.Json;
using NUnit.Framework;
using Roguehalla.Net.Protocol;

namespace Roguehalla.Net.Tests
{
    /// <summary>
    /// The fog mirror against the Rust sight rule. <c>protocol/fixtures/sight_v1.json</c> is generated by
    /// <c>cargo test -p rh-sim vision::golden</c> from the real private functions (<c>scene_line_blocked</c>, <c>reveals_tile</c>) on
    /// the committed seed-1 map; every row must be reproduced exactly, and every mirrored constant must equal the Rust value.
    /// </summary>
    public class SightGoldenTests
    {
        static JsonElement Golden()
        {
            string path = Path.Combine(Util.RepoRoot(), "protocol", "fixtures", "sight_v1.json");
            return JsonDocument.Parse(File.ReadAllText(path)).RootElement;
        }

        static MapBlob Map(JsonElement golden)
        {
            var m = golden.GetProperty("map");
            int w = m.GetProperty("w").GetInt32(), h = m.GetProperty("h").GetInt32();
            byte[] tiles = Convert.FromBase64String(m.GetProperty("tilesB64").GetString());
            byte[] regions = Convert.FromBase64String(m.GetProperty("regionsB64").GetString());
            Assert.AreEqual(w * h, tiles.Length);
            Assert.AreEqual(w * h, regions.Length);
            return new MapBlob((ushort)w, (ushort)h, tiles, null, regions, MapBlob.GroundTerrainOff);
        }

        [Test]
        public void Format_is_the_one_this_test_reads()
        {
            Assert.AreEqual("rh-sight-golden/1", Golden().GetProperty("format").GetString());
        }

        [Test]
        public void Mirrored_constants_equal_the_Rust_values()
        {
            var c = Golden().GetProperty("constants");
            Assert.AreEqual(c.GetProperty("visionRadius").GetDouble(), VisionRule.Radius, "VISION_RADIUS");
            Assert.AreEqual(c.GetProperty("tile").GetDouble(), VisionRule.Tile, "TILE");
            Assert.AreEqual(c.GetProperty("visionTrailMs").GetDouble(), VisionRule.TrailMs, "VISION_TRAIL_MS");
            Assert.AreEqual(c.GetProperty("visionUpdateMs").GetDouble(), VisionRule.UpdateMs, "VISION_UPDATE_MS");
            Assert.AreEqual(c.GetProperty("tickMs").GetDouble(), VisionRule.TickMs, "TICK_MS");
            Assert.AreEqual(c.GetProperty("maskSight").GetInt32(), (int)VisionRule.SightMask, "MASK_SIGHT");
            Assert.AreEqual(c.GetProperty("bushRevealRadius").GetDouble(), VisionRule.BushRevealRadius, "BUSH_REVEAL_RADIUS");
            Assert.AreEqual(c.GetProperty("bushRevealMs").GetDouble(), VisionRule.BushRevealMs, "BUSH_REVEAL_MS");
            Assert.AreEqual(c.GetProperty("regionColiseum").GetInt32(), (int)VisionRule.RegionColiseum, "coliseum region code");
        }

        [Test]
        public void Line_of_sight_agrees_with_Rust_on_every_query()
        {
            var g = Golden();
            var rule = new VisionRule(Map(g));
            int n = 0, blocked = 0;
            foreach (var row in g.GetProperty("blocked").EnumerateArray())
            {
                double ax = row[0].GetDouble(), ay = row[1].GetDouble(), bx = row[2].GetDouble(), by = row[3].GetDouble();
                bool expected = row[4].GetBoolean();
                Assert.AreEqual(expected, rule.LineBlocked(ax, ay, bx, by), "query " + n + " (" + ax + "," + ay + ")->(" + bx + "," + by + ")");
                n++; if (expected) blocked++;
            }
            Assert.GreaterOrEqual(n, 4000);
            Assert.Greater(blocked, n / 10); Assert.Less(blocked, n * 9 / 10); // both verdicts are well represented
        }

        [Test]
        public void Reveal_sets_agree_with_Rust_tile_for_tile()
        {
            var g = Golden();
            var map = Map(g);
            var rule = new VisionRule(map);
            int origins = 0, tiles = 0, revealed = 0;
            foreach (var row in g.GetProperty("reveals").EnumerateArray())
            {
                double ox = row.GetProperty("origin")[0].GetDouble(), oy = row.GetProperty("origin")[1].GetDouble();
                int x0 = row.GetProperty("x0").GetInt32(), y0 = row.GetProperty("y0").GetInt32(), w = row.GetProperty("w").GetInt32(), h = row.GetProperty("h").GetInt32();
                byte[] bits = Convert.FromBase64String(row.GetProperty("bitsB64").GetString());
                for (int y = 0; y < h; y++)
                    for (int x = 0; x < w; x++)
                    {
                        int i = y * w + x;
                        bool expected = (bits[i / 8] >> (i % 8) & 1) != 0;
                        Assert.AreEqual(expected, rule.RevealsTile(ox, oy, x0 + x, y0 + y), "origin " + origins + " (" + ox + "," + oy + ") tile " + (x0 + x) + "," + (y0 + y));
                        tiles++; if (expected) revealed++;
                    }
                var probe = row.GetProperty("inRadiusProbe");
                Assert.AreEqual(probe[0].GetBoolean(), VisionRule.InRadius(ox, oy, ox + VisionRule.Radius, oy), "exactly on the radius");
                Assert.AreEqual(probe[1].GetBoolean(), VisionRule.InRadius(ox, oy, ox + VisionRule.Radius + 0.001, oy), "just past the radius");
                origins++;
            }
            Assert.GreaterOrEqual(origins, 40);
            Assert.Greater(revealed, 1000); Assert.Less(revealed, tiles);
        }

        [Test]
        public void Coliseum_rectangle_derived_from_the_region_plane_equals_the_servers()
        {
            var g = Golden();
            var rule = new VisionRule(Map(g));
            var r = g.GetProperty("map").GetProperty("coliseumRect");
            rule.ColiseumRect(out int x, out int y, out int w, out int h);
            Assert.AreEqual(new[] { r[0].GetInt32(), r[1].GetInt32(), r[2].GetInt32(), r[3].GetInt32() }, new[] { x, y, w, h });
        }
    }
}
